function EffortRange({value,onChange,allowed=[0,1,2,3,4,5]}:{value:number;onChange:(value:number)=>void;allowed?:number[]}){
 const index=Math.max(0,allowed.indexOf(value)),steps=Math.max(1,allowed.length-1);
 const[dragging,setDragging]=useState(false);const start=useRef<number|null>(null);
 const position=`calc(21px + ${index/steps*100}% - ${index/steps*42}px)`;
 function release(){start.current=null;setDragging(false)}
 return <div className="d-effort-slider" data-dragging={dragging}><div className="d-effort-track"><div className="d-effort-progress" style={{width:position}}/>{allowed.map((n,i)=><span key={n} className="d-effort-dot" style={{left:`calc(21px + ${i/steps*100}% - ${i/steps*42}px)`}}/>)}</div><span className="d-effort-thumb" aria-hidden="true" style={{left:position}}/><input aria-label="Reasoning effort" aria-valuetext={effortNames[value]} type="range" min="0" max={allowed.length-1} step="1" value={index} disabled={allowed.length===1} onPointerDown={event=>{event.currentTarget.setPointerCapture?.(event.pointerId);start.current=event.clientX;setDragging(false)}} onPointerMove={event=>{if(start.current!==null&&Math.abs(event.clientX-start.current)>3)setDragging(true)}} onPointerUp={release} onPointerCancel={release} onBlur={release} onChange={event=>onChange(allowed[Number(event.target.value)])}/></div>
}
