 function pinChat(t:string){setPinned(p=>p.includes(t)?p.filter(x=>x!==t):[t,...p])}
 function archiveChat(t:string){setArchived(p=>[...new Set([...p,t])]);if(t===title)newChat();setToast('Chat archived locally')}
 function draftInChat(value:string){newChat();setText(value);setModal('');requestAnimationFrame(()=>area.current?.focus())}
 function selectProject(project:LocalProject){cancelGeneration();agent.save({...agent.config,cwd:project.path});setSelectedProject(project.name);setProjects(previous=>previous.includes(project.name)?previous:[project.name,...previous]);setModal('');setToast('Project: '+project.name)}
 function conversation(t:string){return t===title&&!home?messages:chatContent[t]||[]}
 function menuAction(action:string,target=title){setPopup('');if(action==='Pin'){pinChat(target);return}if(action==='Archive'){archiveChat(target);return}if(action==='Copy conversation'||action==='Copy title'){void navigator.clipboard.writeText(action==='Copy title'?target:conversationMarkdown(target,conversation(target))).then(()=>setToast('Copied'),()=>setToast('Clipboard tidak tersedia'));return}if(action==='Open in new window'||action==='New side chat'){window.open(location.href,'_blank','noopener');return}if(action==='Fork chat'){const base=target+' (fork)';let name=base,n=2;while(titles.includes(name))name=base+' '+n++;const copied=conversation(target).map(message=>({...message}));cancelGeneration();agent.reset();setChatContent(previous=>({...previous,[name]:copied}));setTitles((previous:string[])=>[name,...previous]);setTitle(name);setMessages(copied);setHome(false);setScreen('chat');return}setActionTarget(target);setModal(action==='Add scheduled task...'?'New task':action)}
 function localAction(action:string,value=''){
  const target=actionTarget||title;
  if(action==='rename'){if(value===target){setModal('');setActionTarget('');return}
   cancelGeneration();agent.reset();setTitles((previous:string[])=>previous.map(item=>item===target?value:item));setPinned(previous=>previous.map(item=>item===target?value:item));setArchived(previous=>previous.map(item=>item===target?value:item));
   setChatContent(previous=>{const next={...previous,[value]:conversation(target)};delete next[target];return next});setMembership(previous=>{const next={...previous};if(next[target]){next[value]=next[target];delete next[target]}return next});if(title===target)setTitle(value);
   for(const direction of ['back','forward'] as const)navigationHistory.current[direction]=navigationHistory.current[direction].map(view=>view.title===target?{...view,title:value}:view);
  }else if(action==='delete'){
   setTitles((previous:string[])=>previous.filter(item=>item!==target));setPinned(previous=>previous.filter(item=>item!==target));setArchived(previous=>previous.filter(item=>item!==target));
   setChatContent(previous=>{const next={...previous};delete next[target];return next});setMembership(previous=>{const next={...previous};delete next[target];return next});
   if(title===target)resetChat();for(const direction of ['back','forward'] as const)navigationHistory.current[direction]=navigationHistory.current[direction].filter(view=>view.title!==target);experienceViews.current={};
  }else if(action==='section'){setPinned(previous=>value==='pinned'?[...new Set([target,...previous])]:previous.filter(item=>item!==target))}
  else if(action==='membership'||action==='new-project-membership'){if(action==='new-project-membership')setProjects(previous=>[...new Set([...previous,value])]);setMembership(previous=>({...previous,[target]:value}))}
  else if(action==='restore'){setArchived(previous=>previous.filter(item=>item!==value));setToast('Chat restored');return}
  else if(action==='open'){openChat(value);return}
  else if(action==='backup'){downloadFile('sakelar-chat-backup.json',JSON.stringify({version:1,conversations:[...new Set<string>([...titles,...pinned,...archived])].map(name=>({title:name,messages:conversation(name),pinned:pinned.includes(name),archived:archived.includes(name),project:membership[name]||''}))},null,2),'application/json');return}
  else if(action==='import'){let imported=false;
   try{
    const data=JSON.parse(value),entries=Array.isArray(data.conversations)?data.conversations:[data];
    if(data.version!==1||entries.length>500)throw Error();
    const updates:Record<string,Msg[]>={},importedPinned:string[]=[],importedArchived:string[]=[],importedMembership:Record<string,string>={};
    for(const entry of entries){
     if(typeof entry.title!=='string'||!entry.title.trim()||Object.hasOwn(Object.prototype,entry.title)||!Array.isArray(entry.messages))throw Error();
     let name=entry.title.slice(0,120),i=2;while(titles.includes(name)||Object.hasOwn(updates,name))name=entry.title.slice(0,100)+' (import '+i+++')';
     updates[name]=entry.messages.slice(0,1000).map((message:Msg)=>{if(!message||!['user','assistant'].includes(message.role)||typeof message.text!=='string'||message.text.length>200000)throw Error();if(message.reasoning!==undefined&&(typeof message.reasoning!=='string'||message.reasoning.length>200000))throw Error();return {role:message.role,text:message.text,...(message.reasoning?{reasoning:message.reasoning}:{}),...(typeof message.reasoningDurationMs==='number'&&Number.isFinite(message.reasoningDurationMs)&&message.reasoningDurationMs>=0?{reasoningDurationMs:message.reasoningDurationMs}:{}),timestamp:typeof message.timestamp==='number'?message.timestamp:Date.now()}});
     if(entry.pinned===true)importedPinned.push(name);if(entry.archived===true)importedArchived.push(name);
     if(typeof entry.project==='string'&&entry.project.trim())importedMembership[name]=entry.project.slice(0,100);
    }
    setChatContent(previous=>({...previous,...updates}));setTitles((previous:string[])=>[...Object.keys(updates),...previous]);
    setPinned(previous=>[...previous,...importedPinned]);setArchived(previous=>[...previous,...importedArchived]);
    setMembership(previous=>({...previous,...importedMembership}));setProjects(previous=>[...new Set([...previous,...Object.values(importedMembership)])]);
    setToast(Object.keys(updates).length+' chats added; saving to AXIOM…');imported=true;
   }catch{setToast('Backup tidak valid. Gunakan file JSON ekspor client ini.')}return imported
  }
  else if(action==='access'){cancelGeneration();agent.save({...agent.config,sandbox:value==='workspace-write'?'workspace-write':'read-only'});setToast('Local access updated');return}
  else if(action==='import-preferences'){const valueParsed=JSON.parse(value);if(valueParsed.version!==1||!valueParsed.settings||valueParsed.settings.version!==1||Array.isArray(valueParsed.settings))throw Error('Invalid preferences');saveSettings(valueParsed.settings);return}
  else if(action==='logout'){window.parent.location.assign('/dashboard');return}
  else if(action==='library'){setModal('Files');return}
  else if(action==='dictate'){dictate(draftInChat,setToast);return}

  else if(action==='archive-all'){cancelGeneration();agent.reset();setArchived(previous=>[...new Set([...previous,...titles,...pinned])]);setHome(true);setMessages([]);setTitle('New chat');return}
  else if(action==='delete-all-chats'){cancelGeneration();agent.reset();setTitles([]);setPinned([]);setArchived([]);setChatContent({});setMembership({});setMessages([]);setTitle('New chat');setHome(true);navigationHistory.current={back:[],forward:[]};experienceViews.current={};return}
  else if(action==='settings-tab'){openSettings(value);return}
  else if(action==='profile'){setModal('Edit profile');return}
  else if(action==='agent'){setModal('');agent.setDialog(true);return}
  else if(action==='project'){setModal('Choose project');return}
  else if(action==='files'){setModal('Project files');return}
  else if(action==='archives'){setModal('Archived chats');return}
  else if(action==='storage'){setModal('Storage');return}
  else if(['sites','plugins','skills'].includes(action)){navigate(action as Screen);setModal('');return}
  setModal('');setActionTarget('');setToast('Saved');
 }
